//! Precomputed local Clifford transitions used by the frontier.

use crate::tqe::{PauliU8, TQEType};

pub(super) const TYPE_I: u8 = 0;
pub(super) const TYPE_A: u8 = 1;
pub(super) const TYPE_L: u8 = 2;
pub(super) const TYPE_R: u8 = 3;
pub(super) const TYPE_E: u8 = 4;

/// Result of conjugating two aligned Pauli pairs by one TQE.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct PairReduction {
    /// New left and right Paulis on the first qubit.
    pub(super) q0: [PauliU8; 2],
    /// New left and right Paulis on the second qubit.
    pub(super) q1: [PauliU8; 2],
    /// Sign flips for the left and right Pauli strings.
    pub(super) sign_flips: [bool; 2],
    /// Changes to the A, L, R and E class counts on each qubit.
    pub(super) class_deltas: [[i8; 4]; 2],
}

