#[inline(always)]
/// Returns the support class for one aligned local Pauli pair.
///
/// Pauli values use the base encoding from `pg-bitpacked`. Exhaustive tests
/// compare every entry with the direct conjugation oracle so encoding changes
/// cannot silently leave the table stale.
pub(super) fn pair_type(left: PauliU8, right: PauliU8) -> u8 {
    debug_assert!(left < 4 && right < 4);
    PAIR_TYPE[left as usize * 4 + right as usize]
}

#[inline(always)]
/// Returns one precomputed reducing TQE for a single Pauli string.
///
/// Exhaustive tests compare all candidates with the direct conjugation oracle.
pub(super) fn single_tqes(p0: PauliU8, p1: PauliU8, offset: usize) -> TQEType {
    debug_assert!(p0 < 3 && p1 < 3 && offset < 4);
    SINGLE_TQES[p0 as usize * 12 + p1 as usize * 4 + offset]
}

#[inline(always)]
/// Returns one precomputed reducing TQE for two `A` supports.
///
/// Exhaustive tests compare all candidates with the direct conjugation oracle.
pub(super) fn aa_tqes(
    left0: PauliU8,
    right0: PauliU8,
    left1: PauliU8,
    right1: PauliU8,
    offset: usize,
) -> TQEType {
    debug_assert_eq!(pair_type(left0, right0), TYPE_A);
    debug_assert_eq!(pair_type(left1, right1), TYPE_A);
    debug_assert!(offset < 6);
    AA_TQES[left0 as usize * 162
        + right0 as usize * 54
        + left1 as usize * 18
        + right1 as usize * 6
        + offset]
}

#[inline(always)]
/// Looks up the single string Clifford transition, sign flip and support
/// changes for one local Pauli and TQE combination.
///
/// Exhaustive tests compare every transition with the direct conjugation oracle.
pub(super) fn single_reduction_with_all_stats(
    p0: PauliU8,
    p1: PauliU8,
    gate: TQEType,
) -> (PauliU8, PauliU8, bool, i8, i8) {
    debug_assert!(p0 < 4 && p1 < 4 && gate < 9);
    SINGLE_REDUCTION_WITH_ALL_STATS[p0 as usize * 36 + p1 as usize * 9 + gate as usize]
}

#[inline(always)]
/// Looks up the paired Clifford transition, sign flips and support class
/// changes for one local Pauli pair and TQE combination.
///
/// Exhaustive tests compare every transition with the direct conjugation oracle.
pub(super) fn pair_reduction(
    left0: PauliU8,
    right0: PauliU8,
    left1: PauliU8,
    right1: PauliU8,
    gate: TQEType,
) -> PairReduction {
    debug_assert!(left0 < 4 && right0 < 4 && left1 < 4 && right1 < 4 && gate < 9);
    PAIR_REDUCTIONS[left0 as usize * 576
        + right0 as usize * 144
        + left1 as usize * 36
        + right1 as usize * 9
        + gate as usize]
}

